//! Arbitration/persistence fault tests with synthetic event archives.
//! Actual full-model replay is covered separately by target_competition_v2.mjs.
use ed25519_dalek::{Signer,SigningKey};
use flypow::target_authority::*;
use flypow_target_protocol::{self as p,CandidateManifest,TrialArtifact,GoalSpec};
use serde_json::{Value,json};
use std::{path::PathBuf,sync::Arc};
fn keys()->Vec<SigningKey>{(1..=5).map(|i|SigningKey::from_bytes(&[i;32])).collect()}
fn request(k:&SigningKey,action:&str,rid:&str,payload:Value,name:&str)->SignedRequest{let mut r=SignedRequest{public_key:p::hex(k.verifying_key().as_bytes()),action:action.into(),request_id:name.into(),round_id:rid.into(),payload,signature:String::new()};r.signature=p::hex(&k.sign(&p::unhex(&p::id("authority-action",&r.unsigned()).unwrap()).unwrap()).to_bytes());r}
fn open(dir:&std::path::Path)->Arc<Authority>{let k=keys();Authority::open(dir.into(),AuthorityConfig{schema:"flypow-target-authority-config-v2".into(),network_id:"state-fixture-v2".into(),campaign_id:"one-scientific-goal".into(),family_paths:vec![],goal_paths:vec![PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("web/data/target-mining-v2/brief/goal.json")],verifier_keys:k[..3].iter().map(|k|p::hex(k.verifying_key().as_bytes())).collect(),admin_keys:vec![p::hex(k[4].verifying_key().as_bytes())],allowed_origins:vec!["http://127.0.0.1:8084".into()],tau_seconds:300,search_seconds:120,reveal_seconds:60,verification_seconds:1200,max_queue:8,per_identity_claims:2,max_private_bytes:512*1024*1024}).unwrap()}
fn fixture(round:&Value)->(CandidateManifest,Vec<u8>){let g:GoalSpec=serde_json::from_value(round["goal"].clone()).unwrap();let x=p::CandidateInput{stimulated_body_id:"16789".into(),start_step:32,end_step:33,current:150};let mut events=if g.response_set.len()==12{g.response_set.iter().flat_map(|m|(33u32..81).map(move |step|(step,m.model_index))).collect::<Vec<_>>()}else{g.response_set.iter().flat_map(|m|[(33u32,m.model_index),(49u32,m.model_index),(50u32,m.model_index)]).collect::<Vec<_>>()};events.sort();let mut b=vec![0;480];b[..8].copy_from_slice(b"FBRP1\0\0\0");for (at,n) in [(8,g.neuron_count),(12,g.validate_input(&x).unwrap()),(16,256),(476,events.len() as u32)]{b[at..at+4].copy_from_slice(&n.to_le_bytes());}b[32..40].copy_from_slice(&(events.len() as u64).to_le_bytes());for (s,i) in events{b.extend(s.to_le_bytes());b.extend(i.to_le_bytes());}let rid=round["roundId"].as_str().unwrap();let trials=(0..2).map(|j|TrialArtifact{trial_id:p::trial_id(rid,&g,&x,j,round["seeds"][j as usize].as_str().unwrap()).unwrap(),repeat_index:j,seed_hex:round["seeds"][j as usize].as_str().unwrap().into(),result_root:p::hash(&b),bytes:b.len() as u64,metrics:p::evaluate(&g,&x,&b).unwrap()}).collect::<Vec<_>>();let m=CandidateManifest{schema:"flypow-candidate-manifest-v2".into(),round_id:rid.into(),goal_id:g.goal_id().unwrap(),candidate_id:p::candidate_id(rid,&x).unwrap(),input:x,goal_result_root:p::result_root(&trials).unwrap(),trials};(m,b)}
fn commit(a:&Authority,k:&SigningKey,r:&Value,m:&CandidateManifest,salt:&str,name:&str,t:u64)->Value{let miner=p::hex(k.verifying_key().as_bytes());let c=p::commitment(r,&miner,m,salt).unwrap();a.claim(&request(k,"claim",&m.round_id,json!({"commitment":c}),name),t).unwrap()}
fn reveal(a:&Authority,k:&SigningKey,m:&CandidateManifest,b:&[u8],cid:&str,salt:&str,t:u64){for j in 0..2{let u=a.upload_create(&request(k,"upload-create",&m.round_id,json!({"claimId":cid,"trialIndex":j,"bytes":b.len(),"sha256":p::hash(b)}),&format!("upload-{cid}-{j}")),t).unwrap();let uid=u["uploadId"].as_str().unwrap();assert!(a.seal(&request(k,"upload-seal",&m.round_id,json!({"uploadId":uid}),&format!("unsealed-{uid}")),uid,t).is_err());let r=request(k,"upload-chunk",&m.round_id,json!({"uploadId":uid,"index":0,"bytes":b.len(),"sha256":p::hash(b)}),&format!("chunk-{uid}"));a.upload_chunk(&r,uid,0,b,t).unwrap();a.upload_chunk(&r,uid,0,b,t).unwrap();a.seal(&request(k,"upload-seal",&m.round_id,json!({"uploadId":uid}),&format!("sealed-{uid}")),uid,t).unwrap();}
let req=request(k,"reveal",&m.round_id,json!({"claimId":cid,"manifest":m,"salt":salt}),&format!("reveal-{cid}"));a.reveal(&req,cid,t).unwrap();a.reveal(&req,cid,t).unwrap();let req=request(k,"reveal",&m.round_id,req.payload.clone(),&format!("recovery-{cid}"));a.reveal(&req,cid,t).unwrap();}
fn vote(a:&Authority,k:&SigningKey,r:&Value,m:&CandidateManifest,t:u64,valid:bool)->Value{let lease=a.lease(&request(k,"verifier-lease","",json!({}),"lease-request"),t).unwrap();let j=&lease["job"];let cid=j["claimId"].as_str().unwrap();let payload=json!({"jobId":j["jobId"],"fencingToken":j["fencingToken"],"networkId":r["pre"]["networkId"],"claimId":cid,"roundId":m.round_id,"goalId":m.goal_id,"candidateId":m.candidate_id,"goalResultRoot":m.goal_result_root,"manifestHash":p::id("candidate-manifest",&p::value(m)).unwrap(),"evaluatorVersion":r["goal"]["evaluatorVersion"],"difficultyPolicyHash":r["pre"]["difficultyPolicyHash"],"verificationPolicyHash":p::id("verification-policy",&r["pre"]["verificationPolicy"]).unwrap(),"completeTrials":2,"fullReplay":true,"valid":valid});let req=request(k,"verifier-vote",&m.round_id,payload,&format!("vote-{}-{}",&cid[..16],&p::hex(k.verifying_key().as_bytes())[..16]));let v=a.vote(&req,t).unwrap();a.vote(&req,t).unwrap();v}
#[test]fn sequence_priority_restart_idempotency_and_unique_finalizers(){let dir=tempfile::tempdir().unwrap();let mut a=open(dir.path());a.maintain(10000).unwrap();let r=a.current().unwrap()["round"].clone();let (m,b)=fixture(&r);let k=keys();let sa="1".repeat(64);let sb="2".repeat(64);let aa=commit(&a,&k[3],&r,&m,&sa,"commit-miner-A",10001);let bb=commit(&a,&k[4],&r,&m,&sb,"commit-miner-B",10002);assert_eq!(aa["claimSequence"],1);assert_eq!(bb["claimSequence"],2);let again=commit(&a,&k[3],&r,&m,&sa,"commit-miner-A",10020);assert_eq!(again,aa);
let ac=aa["claimId"].as_str().unwrap();let bc=bb["claimId"].as_str().unwrap();reveal(&a,&k[4],&m,&b,bc,&sb,10003);vote(&a,&k[0],&r,&m,10004,true);vote(&a,&k[1],&r,&m,10005,true);assert!(a.round_state(&m.round_id).unwrap()["winner"].is_null());reveal(&a,&k[3],&m,&b,ac,&sa,10006);vote(&a,&k[0],&r,&m,10007,true);drop(a);a=open(dir.path());vote(&a,&k[1],&r,&m,10008,true);let x=a.clone();let y=open(dir.path());let t=std::thread::spawn(move||x.maintain(10009).unwrap());y.maintain(10009).unwrap();t.join().unwrap();let w=a.round_state(&m.round_id).unwrap();assert_eq!(w["winner"]["claimId"],ac);assert_eq!(a.stats().unwrap()["confirmedRounds"],1);let measured=a.statistics_at(10009).unwrap();assert_eq!(measured["metrics"]["validClaims"]["value"],2);assert_eq!(measured["metrics"]["uniqueCandidates"]["value"],1);assert_eq!(measured["metrics"]["completeBackgrounds"]["value"],2);assert_eq!(measured["metrics"]["replayReports"]["value"],4);assert_eq!(measured["verificationQueue"],0,"unused assignments for terminal quorum claims are audit history, not runnable queue");assert_eq!(a.claim_state(ac).unwrap()["verificationQueue"],0);assert_eq!(a.current().unwrap()["state"],"RESEARCH_STAGE_COMPLETE");let cap=a.current().unwrap()["capabilities"].clone();assert_eq!(cap["controller"]["validSamples"],1);assert_eq!(cap["currentRoundAvailable"],false);assert_eq!(cap["basisRoundId"],r["roundId"]);let e=a.events(0).unwrap();let events=e["events"].as_array().unwrap();assert_eq!(events.iter().filter(|e|e["kind"]=="ROUND_FINALIZED").count(),1);assert!(a.events(events.last().unwrap()["eventSequence"].as_u64().unwrap()).unwrap()["events"].as_array().unwrap().is_empty());}
#[test]fn unrevealed_claim_expires_without_blocking_later_valid(){let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.maintain(20000).unwrap();let r=a.current().unwrap()["round"].clone();let (m,b)=fixture(&r);let k=keys();let sa="3".repeat(64);let sb="4".repeat(64);let aa=commit(&a,&k[3],&r,&m,&sa,"occupying-claim",20001);let bb=commit(&a,&k[4],&r,&m,&sb,"eligible-claim",20002);let bc=bb["claimId"].as_str().unwrap();reveal(&a,&k[4],&m,&b,bc,&sb,20003);vote(&a,&k[0],&r,&m,20004,true);vote(&a,&k[1],&r,&m,20005,true);a.maintain(20062).unwrap();assert_eq!(a.claim_state(aa["claimId"].as_str().unwrap()).unwrap()["status"],"TIMED_OUT");assert_eq!(a.round_state(&m.round_id).unwrap()["winner"]["claimId"],bc);}
#[test]fn authorization_future_freeze_and_fencing(){let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.maintain(30000).unwrap();let r=a.current().unwrap()["round"].clone();let (m,b)=fixture(&r);let k=keys();let salt="5".repeat(64);let c=commit(&a,&k[3],&r,&m,&salt,"first-candidate",30001);let cid=c["claimId"].as_str().unwrap();reveal(&a,&k[3],&m,&b,cid,&salt,30002);let first=a.lease(&request(&k[0],"verifier-lease","",json!({}),"lease-original"),30003).unwrap();let newer=a.lease(&request(&k[0],"verifier-lease","",json!({}),"lease-new-owner"),30304).unwrap();assert!(newer["job"]["fencingToken"].as_u64()>first["job"]["fencingToken"].as_u64());let stale=request(&k[0],"verifier-heartbeat",&m.round_id,json!({"jobId":first["job"]["jobId"],"fencingToken":first["job"]["fencingToken"]}),"stale-heartbeat");assert!(a.heartbeat(&stale,30305).is_err());let mut policy=a.config.policy();policy["tauSeconds"]=json!(500);let bad=request(&k[3],"publish-future-policy","",json!({"policy":policy}),"unauthorized-admin");assert!(a.publish_policy(&bad,30305).is_err());a.publish_policy(&request(&k[4],"publish-future-policy","",bad.payload.clone(),"authorized-admin"),30305).unwrap();assert_eq!(a.current().unwrap()["round"],r);let mut fake=request(&k[3],"claim",&m.round_id,json!({"commitment":"6".repeat(64)}),"fake-signature");fake.signature="0".repeat(128);assert!(a.claim(&fake,30004).is_err());}
#[test]fn empty_closed_round_retries_without_erasing_admitted_eligibility(){let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.maintain(40000).unwrap();let r=a.current().unwrap()["round"].clone();a.maintain(40121).unwrap();assert!(a.current().unwrap()["round"].is_null());assert_eq!(a.current().unwrap()["state"],"SUPPLY_DEFERRED");a.maintain(40182).unwrap();let next=a.current().unwrap()["round"].clone();assert_ne!(r["roundId"],next["roundId"]);assert_eq!(r["goal"],next["goal"]);assert_eq!(a.round_state(r["roundId"].as_str().unwrap()).unwrap()["status"],"EXPIRED_NO_VALID_RESULT");assert!(a.maintain(40001).is_err());assert_eq!(a.stats().unwrap()["confirmedRounds"],0);}

fn live_open(dir:&std::path::Path)->Arc<Authority>{
 let k=keys();let root=PathBuf::from(env!("CARGO_MANIFEST_DIR"));Authority::open(dir.into(),AuthorityConfig{schema:"flypow-target-authority-config-v2".into(),network_id:"synthetic-family-state-test".into(),campaign_id:"three-goal-family-isolation".into(),family_paths:vec![root.join("web/data/target-mining-v2/comparable-family-20261011.json")],goal_paths:vec![root.join("web/data/target-mining-v2/live-group-1-20261011/goal.json"),root.join("web/data/target-mining-v2/live-group-2-20261011/goal.json"),root.join("web/data/target-mining-v2/brief/goal.json")],verifier_keys:k[..3].iter().map(|k|p::hex(k.verifying_key().as_bytes())).collect(),admin_keys:vec![p::hex(k[4].verifying_key().as_bytes())],allowed_origins:vec!["http://127.0.0.1:8084".into()],tau_seconds:300,search_seconds:120,reveal_seconds:60,verification_seconds:1200,max_queue:8,per_identity_claims:2,max_private_bytes:512*1024*1024}).unwrap()
}
#[test]fn readonly_readiness_and_comparable_statistics_survive_goal_change_restart_and_other_family(){
 let dir=tempfile::tempdir().unwrap();let mut a=live_open(dir.path());assert_eq!(a.readiness().unwrap()["roundCount"],0);assert_eq!(a.readiness().unwrap()["roundCount"],0);assert!(a.current().unwrap()["round"].is_null());assert!(a.events(0).unwrap()["events"].as_array().unwrap().is_empty());
 let k=keys();let mut first_family=Value::Null;
 for n in 0..2{let at=50000+n*10;a.maintain(at).unwrap();let r=a.current().unwrap()["round"].clone();p::validate_round(&r).unwrap();let cap=a.current().unwrap()["capabilities"].clone();if n==0{first_family=cap["familyId"].clone();}else{assert_eq!(cap["familyId"],first_family);assert_eq!(cap["controller"]["validSamples"],1);}assert_eq!(r["pre"]["requiredBackgrounds"],2);let (m,b)=fixture(&r);assert!(m.trials.iter().all(|t|t.metrics.passed));let salt=format!("{:064x}",n+1);let c=commit(&a,&k[3],&r,&m,&salt,&format!("family-claim-{n}"),at+1);reveal(&a,&k[3],&m,&b,c["claimId"].as_str().unwrap(),&salt,at+2);vote(&a,&k[0],&r,&m,at+3,true);vote(&a,&k[1],&r,&m,at+4,true);assert_eq!(a.stats().unwrap()["difficultyController"]["validSamples"],n+1);drop(a);a=live_open(dir.path());}
 a.maintain(50020).unwrap();let c=a.current().unwrap()["capabilities"].clone();assert_ne!(c["familyId"],first_family);assert_eq!(c["controller"]["validSamples"],0);let db=rusqlite::Connection::open(dir.path().join("target-v2.sqlite")).unwrap();let persisted:String=db.query_row("SELECT controller_json FROM difficulty_family_controllers WHERE family_id=?",[first_family.as_str().unwrap()],|r|r.get(0)).unwrap();assert_eq!(serde_json::from_str::<Value>(&persisted).unwrap()["validSamples"],2);
 // Synthetic votes exercise persisted arbitration only, not science/discovery.
}
#[test]fn future_plan_append_is_authenticated_audited_and_leaves_open_round_frozen(){
 let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.maintain(60000).unwrap();let r=a.current().unwrap()["round"].clone();let root=PathBuf::from(env!("CARGO_MANIFEST_DIR"));let mut append=Vec::new();for n in 1..=2{let d=root.join(format!("web/data/target-mining-v2/live-group-{n}-20261011"));append.push(json!({"goal":serde_json::from_slice::<Value>(&std::fs::read(d.join("goal.json")).unwrap()).unwrap(),"calibration":serde_json::from_slice::<Value>(&std::fs::read(d.join("calibration.json")).unwrap()).unwrap()}));}
 let family:Value=serde_json::from_slice(&std::fs::read(root.join("web/data/target-mining-v2/comparable-family-20261011.json")).unwrap()).unwrap();let plan=json!({"schema":"flypow-target-plan-revision-v1","revision":1,"previousPlanHash":null,"source":"frozen-measurement-state-test","append":append,"families":[family]});let k=keys();assert!(a.publish_plan(&request(&k[3],"publish-future-plan","",json!({"plan":plan}),"unauthorized-plan"),60001).is_err());let req=request(&k[4],"publish-future-plan","",json!({"plan":plan}),"append-plan");let receipt=a.publish_plan(&req,60001).unwrap();assert_eq!(a.publish_plan(&req,60001).unwrap(),receipt);assert_eq!(a.current().unwrap()["round"],r);let mut duplicate=plan;duplicate["revision"]=json!(2);duplicate["previousPlanHash"]=receipt["planHash"].clone();assert!(a.publish_plan(&request(&k[4],"publish-future-plan","",json!({"plan":duplicate}),"duplicate-plan"),60002).is_err());drop(a);let restored=open(dir.path());assert_eq!(restored.current().unwrap()["round"],r);assert_eq!(restored.events(0).unwrap()["events"].as_array().unwrap().iter().filter(|e|e["kind"]=="FUTURE_PLAN_APPENDED").count(),1);
}

#[test]
fn queued_request_clock_is_sampled_inside_transaction() {
 let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.use_wall_clock();let at=now();a.maintain(at).unwrap();let frozen=a.current().unwrap()["round"].clone();a.maintain(at.saturating_sub(2)).unwrap();assert_eq!(frozen,a.current().unwrap()["round"]);
 let other=tempfile::tempdir().unwrap();let b=open(other.path());b.maintain(10_000).unwrap();assert!(b.maintain(9_999).unwrap_err().contains("CLOCK_ROLLBACK"));
}

#[test]
fn scientific_task_aliases_cannot_expand_supply_and_failed_batches_are_atomic() {
 let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.maintain(65000).unwrap();
 let frozen=a.current().unwrap()["round"].clone();let before=a.readiness().unwrap()["supply"].clone();
 let root=PathBuf::from(env!("CARGO_MANIFEST_DIR"));let k=keys();
 let item=|path:&str|{let d=root.join(path);json!({"goal":serde_json::from_slice::<Value>(&std::fs::read(d.join("goal.json")).unwrap()).unwrap(),"calibration":serde_json::from_slice::<Value>(&std::fs::read(d.join("calibration.json")).unwrap()).unwrap()})};
 let rename=|mut item:Value|{item["goal"]["description"]=json!("Different public label, exactly the same frozen scientific task");let mut definition=item["goal"].clone();definition.as_object_mut().unwrap().remove("calibrationHash");item["calibration"]["scientificDefinitionHash"]=json!(p::id("calibration-science",&definition).unwrap());item["goal"]["calibrationHash"]=json!(p::hash(&p::canonical(&item["calibration"]).unwrap()));item};
 let original=item("web/data/target-mining-v2/brief");let alias=rename(original.clone());
 let old_goal:GoalSpec=serde_json::from_value(original["goal"].clone()).unwrap();let new_goal:GoalSpec=serde_json::from_value(alias["goal"].clone()).unwrap();
 assert_ne!(old_goal.goal_id().unwrap(),new_goal.goal_id().unwrap());assert_eq!(flypow::product_identity::task(&old_goal).unwrap(),flypow::product_identity::task(&new_goal).unwrap());
 let fresh=item("web/data/target-mining-v2/live-group-1-20261011");
 for (n,append) in [vec![alias],vec![fresh.clone(),rename(fresh.clone())]].into_iter().enumerate(){
  let plan=json!({"schema":"flypow-target-plan-revision-v1","revision":1,"previousPlanHash":null,"source":"isolated-scientific-supply-regression","append":append});
  let error=a.publish_plan(&request(&k[4],"publish-future-plan","",json!({"plan":plan}),&format!("alias-plan-{n}")),65001+n as u64).unwrap_err();assert!(error.contains("scientific task already registered"),"{error}");
  assert_eq!(a.readiness().unwrap()["supply"],before);assert_eq!(a.current().unwrap()["round"],frozen);
 }
 // The first item of a rejected batch was rolled back, so it can now be
 // published once with the original revision and previous-plan identity.
 let plan=json!({"schema":"flypow-target-plan-revision-v1","revision":1,"previousPlanHash":null,"source":"isolated-valid-after-rollback","append":[fresh]});
 a.publish_plan(&request(&k[4],"publish-future-plan","",json!({"plan":plan}),"valid-after-alias-rejection"),65003).unwrap();
 assert_eq!(a.current().unwrap()["round"],frozen);
 let mut other=a.config.clone();other.campaign_id="different-name-same-science".into();drop(a);
 assert!(Authority::open(dir.path().into(),other).err().unwrap().contains("scientific task already registered"));
 let restored=open(dir.path());assert_eq!(restored.current().unwrap()["round"],frozen);
 assert_eq!(restored.events(0).unwrap()["events"].as_array().unwrap().iter().filter(|e|e["kind"]=="FUTURE_PLAN_APPENDED").count(),1);
}

#[test]
fn private_records_trace_the_winner_without_publishing_it() {
 let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.maintain(66000).unwrap();let r=a.current().unwrap()["round"].clone();let (m,b)=fixture(&r);let k=keys();let salt="7".repeat(64);
 let c=commit(&a,&k[3],&r,&m,&salt,"record-trace-candidate",66001);reveal(&a,&k[3],&m,&b,c["claimId"].as_str().unwrap(),&salt,66002);vote(&a,&k[0],&r,&m,66003,true);vote(&a,&k[1],&r,&m,66004,true);
 let query=request(&k[3],"product-records","",json!({}),"owner-trace-query");let records=a.product_records(&query).unwrap();let row=&records["contributions"][0];
 assert_eq!(records["contributions"].as_array().unwrap().len(),1);assert_eq!(row["goalId"],m.goal_id);assert_eq!(row["roundId"],m.round_id);assert_eq!(row["candidateId"],m.candidate_id);assert!(!row["acceptanceId"].is_null());assert!(row["publicResultId"].is_null());
 assert_eq!(a.product_results(&Default::default()).unwrap()["items"],json!([]));
 let other=request(&k[4],"product-records","",json!({}),"other-identity-query");assert_eq!(a.product_records(&other).unwrap()["contributions"],json!([]));
 let mut forged=query.clone();forged.public_key=other.public_key;assert!(a.product_records(&forged).is_err());
 drop(a);let restored=open(dir.path());assert_eq!(restored.product_records(&query).unwrap()["contributions"],records["contributions"]);
}

#[test]
fn signed_work_reports_dedupe_resets_expiry_windows_and_restart() {
 let dir=tempfile::tempdir().unwrap();let a=open(dir.path());let k=keys();let at=80_000;
 let payload=|seq:u64,n:&str,s:&str,t:u64|json!({"schema":"flypow-session-work-report-v1","networkId":a.config.network_id,"authorityId":a.authority_id,"campaignId":a.config.campaign_id,"sessionId":"meter-session-A","roundId":"","sequence":seq,"producedAt":t*1000,"phase":"computing","neuronUpdates":n,"synapseAdditions":s});
 assert!(a.statistics_at(at).unwrap()["metrics"]["selfReportedNeuronUpdates"]["work"].is_null());
 let r=request(&k[3],"session-work-report","",payload(1,"0","0",at),"work-report-1");a.report_work(&r,at).unwrap();let duplicate=a.report_work(&r,at).unwrap();assert_eq!(duplicate["duplicate"],true);
 assert_eq!(a.statistics_at(at).unwrap()["metrics"]["selfReportedNeuronUpdates"]["status"],"sampling");
 let second=request(&k[3],"session-work-report","",payload(2,"3000","9000",at+3),"work-report-2");a.report_work(&second,at+3).unwrap();let x=a.statistics_at(at+3).unwrap();assert_eq!(x["metrics"]["selfReportedNeuronUpdates"]["work"],"3000");assert_eq!(x["metrics"]["selfReportedSynapseAdditions"]["work"],"9000");assert_eq!(x["metrics"]["selfReportedNeuronUpdates"]["windowMs"],30000);
 let receipt=a.report_work(&second,at+4).unwrap();assert_eq!(receipt["duplicate"],true);
 let reset=request(&k[3],"session-work-report","",payload(3,"1","1",at+6),"work-reset-bad");assert!(a.report_work(&reset,at+6).unwrap_err().contains("counter reset"));
 let fast=request(&k[3],"session-work-report","",payload(3,"4000","10000",at+4),"work-fast-bad");assert!(a.report_work(&fast,at+4).unwrap_err().contains("BACKPRESSURE"));
 let mut forged=second.clone();forged.signature="0".repeat(128);assert!(a.report_work(&forged,at+5).is_err());
 assert_eq!(a.statistics_at(at+33).unwrap()["metrics"]["selfReportedNeuronUpdates"]["status"],"sampling","no received interval in this window is not a measured zero");
 let mut idle=payload(3,"3000","9000",at+33);idle["phase"]=json!("waiting");a.report_work(&request(&k[3],"session-work-report","",idle,"work-measured-zero"),at+33).unwrap();
 assert_eq!(a.statistics_at(at+33).unwrap()["metrics"]["selfReportedNeuronUpdates"]["work"],"0","measured zero is distinct from missing work");
 let stale=a.statistics_at(at+80).unwrap();assert_eq!(stale["metrics"]["selfReportedNeuronUpdates"]["status"],"stale");assert!(stale["metrics"]["selfReportedNeuronUpdates"]["work"].is_null());
 let pubkey=a.authority_id.clone();drop(a);let restored=open(dir.path());assert_eq!(restored.authority_id,pubkey);assert_eq!(restored.statistics_at(at+3).unwrap()["metrics"]["selfReportedNeuronUpdates"]["work"],"3000");assert!(restored.report_work(&second,at+100).unwrap_err().contains("expired"));assert_eq!(restored.round_history(0,20).unwrap()["rounds"],json!([]));
}

#[test]
fn round_history_and_statistics_signature_are_persistent() {
 let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.maintain(90_000).unwrap();let history=a.round_history(0,1).unwrap();assert_eq!(history["rounds"][0]["roundSequence"],1);assert_eq!(history["nextBefore"],1);assert_eq!(a.round_history(1,20).unwrap()["rounds"],json!([]));
 let mut stats=a.statistics_at(90_001).unwrap();let sig=p::unhex(stats.as_object_mut().unwrap().remove("signature").unwrap().as_str().unwrap()).unwrap();let bytes=p::unhex(&p::id("network-stats",&stats).unwrap()).unwrap();let key=p::unhex(&a.authority_id).unwrap();let key=ed25519_dalek::VerifyingKey::from_bytes(&key.try_into().unwrap()).unwrap();key.verify_strict(&bytes,&ed25519_dalek::Signature::from_slice(&sig).unwrap()).unwrap();assert_eq!(stats["metrics"]["uniqueCandidates"]["value"],0);assert_eq!(stats["supply"]["remainingUnopenedGoals"],0);assert_eq!(a.current().unwrap()["modelIdentity"]["graphRoot"],"6c42f6ff8e2198aca17a765acae0475b490abb0169d615e32b71c976f563deb4");
}

#[test]
fn product_supply_is_bound_to_real_calibration_and_cold_starts() {
 let root=PathBuf::from(env!("CARGO_MANIFEST_DIR"));let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.maintain(100_000).unwrap();let frozen=a.current().unwrap()["round"].clone();
 let base=root.join("web/data/target-mining-v2");let family:p::family::Family=serde_json::from_slice(&std::fs::read(base.join("product-family-20261011.json")).unwrap()).unwrap();let mut evidence=Vec::new();let mut append=Vec::new();let mut cells=std::collections::BTreeSet::new();let old:GoalSpec=serde_json::from_value(frozen["goal"].clone()).unwrap();
 for n in 1..=24 {let d=base.join(format!("product-group-{n}-20261011"));let g:GoalSpec=serde_json::from_slice(&std::fs::read(d.join("goal.json")).unwrap()).unwrap();let c:Value=serde_json::from_slice(&std::fs::read(d.join("calibration.json")).unwrap()).unwrap();g.validate().unwrap();for m in &g.response_set {assert!(cells.insert(m.model_index));assert!(!old.response_set.iter().chain(&old.stimulus_set).chain(&old.off_target_set).any(|old|old.model_index==m.model_index));}append.push(json!({"goal":g,"calibration":c}));evidence.push((g,c));}
 family.validate_evidence(&evidence).unwrap();assert_eq!(family.members.len(),24);assert_eq!(family.levels.len(),2);let k=keys();let plan=json!({"schema":"flypow-target-plan-revision-v1","revision":1,"previousPlanHash":null,"source":"product-measured-supply-test","append":append,"families":[family]});let req=request(&k[4],"publish-future-plan","",json!({"plan":plan}),"product-measured-plan");a.publish_plan(&req,100_001).unwrap();assert_eq!(a.current().unwrap()["round"],frozen);assert_eq!(a.current().unwrap()["supply"]["remainingUnopenedGoals"],24);drop(a);let restored=open(dir.path());assert_eq!(restored.current().unwrap()["supply"]["remainingUnopenedGoals"],24);
 let db=rusqlite::Connection::open(dir.path().join("target-v2.sqlite")).unwrap();let inherited:u64=db.query_row("SELECT COUNT(*) FROM difficulty_family_controllers WHERE family_id=?",[family.identity().unwrap()],|r|r.get(0)).unwrap();assert_eq!(inherited,0,"a new plan cannot import old samples before opening its first round");
}

#[test]fn finalized_round_laggards_expire_and_projection_is_read_only(){
 let dir=tempfile::tempdir().unwrap();let a=open(dir.path());a.maintain(190000).unwrap();let r=a.current().unwrap()["round"].clone();let(m,b)=fixture(&r);let k=keys();
 let winner=commit(&a,&k[3],&r,&m,&"a".repeat(64),"winner-source-190",190001);let late=commit(&a,&k[4],&r,&m,&"b".repeat(64),"late-source-190",190002);
 reveal(&a,&k[3],&m,&b,winner["claimId"].as_str().unwrap(),&"a".repeat(64),190003);vote(&a,&k[0],&r,&m,190004,true);vote(&a,&k[1],&r,&m,190005,true);
 assert_eq!(a.round_state(&m.round_id).unwrap()["status"],"FINALIZED");a.maintain(190064).unwrap();assert_eq!(a.claim_state(late["claimId"].as_str().unwrap()).unwrap()["status"],"TIMED_OUT");
 let archived=a.archive_housekeeping(190064).unwrap();assert_eq!(archived["temporaryBytes"],"0");a.project_explorer().unwrap();
 let before=a.events(0).unwrap();let q=flypow::explorer_types::ExplorerQuery::default();let records=a.explorer_query("records",&q).unwrap();assert_eq!(records["items"].as_array().unwrap().len(),1);let record=&records["items"][0];let id=record["recordId"].as_str().unwrap();
 assert_eq!(a.explorer_query(&format!("records/{id}"),&q).unwrap()["data"]["claimId"],winner["claimId"]);a.explorer_query("overview",&q).unwrap();a.explorer_query("network",&q).unwrap();assert_eq!(a.events(0).unwrap(),before);
 let public=records.to_string();assert!(!public.contains(&"b".repeat(64)));assert!(!public.contains("fencingToken"));assert!(!public.contains("accessToken"));assert!(!public.contains("private/artifacts"));
 // A new indexer from the same immutable sources reconstructs the same ID/root.
 let index=dir.path().join("rebuilt.sqlite");flypow::explorer_projection::project(dir.path(),&index,&a.config.network_id,&a.authority_id,&a.config.campaign_id).unwrap();let c=flypow::explorer_projection::source_open(&index).unwrap();let rebuilt=flypow::explorer::query_index(&c,"records",&q).unwrap();assert_eq!(rebuilt["items"][0]["recordId"],record["recordId"]);assert_eq!(rebuilt["items"][0]["evidence"],record["evidence"]);
}
#[test]fn difficult_future_goal_defers_without_becoming_solved(){
 let d=tempfile::tempdir().unwrap();let a=live_open(d.path());a.maintain(300000).unwrap();let first=a.current().unwrap()["round"].clone();a.maintain(300121).unwrap();let second=a.current().unwrap()["round"].clone();assert!(!second.is_null());assert_ne!(first["pre"]["goalId"],second["pre"]["goalId"]);assert_eq!(a.current().unwrap()["supply"]["solvedGoals"],0);assert_eq!(a.round_state(first["roundId"].as_str().unwrap()).unwrap()["status"],"EXPIRED_NO_VALID_RESULT");
}
